contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        uint256 beforeBalance = c.tokenBalance(address(this));

        bool firstReverted;
        try c.airDrop() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 afterFirst = c.tokenBalance(address(this));

        bool secondReverted;
        try c.airDrop() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 afterSecond = c.tokenBalance(address(this));

        assert(
            firstReverted ||
            (
                afterFirst >= beforeBalance + 20 &&
                afterSecond == afterFirst &&
                secondReverted
            )
        );
    }
}

