    }

    function run(uint balanceSeed) public {
        require(balanceSeed == 0 || balanceSeed == 1);

        if (balanceSeed == 1) {
            c.airDrop();
        }

        uint before = c.tokenBalance(address(this));
        bool reverted;

        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.tokenBalance(address(this));

        if (reverted) {
            assert(afterBal == before);
        } else {
            assert(afterBal == before + 20);
        }
